H("684.d.5.A",3,"Polite and respectful messages online show:","good digital behavior",["poor behavior","rudeness","disregard"],"Respectful messages are appropriate.")
H("684.d.5.A",4,"The rules for polite communication online are often called:","netiquette",["geography","trigonometry","botany"],"Netiquette guides online conduct.")
H("684.d.5.B",3,"Repeatedly sending hurtful messages to a person online is:","cyberbullying",["tutoring","teamwork","research"],"Online bullying harms people.")
H("684.d.5.B",4,"A lasting effect of posting something embarrassing online is that it can:","stay visible and affect reputation later",["vanish forever at once","never be seen","improve every grade"],"Online posts can persist.")
H("684.d.5.C",3,"Which is a strong way to protect your online accounts?","use a unique password for each account",["share your passwords","use the same password everywhere","write it on a public note"],"Unique passwords limit damage.")
H("684.d.5.C",4,"Giving out your home address in a public forum is risky because it can:","let strangers find where you live",["improve your reputation","earn rewards","protect you"],"Limit personal information online.")
H("684.d.5.D",3,"Using licensed media and giving credit are examples of:","legal and responsible technology use",["unsafe behavior","risky actions","illegal habits"],"Responsible use follows law.")
H("684.d.5.D",4,"A student who tells classmates about phishing scams is practicing:","advocacy for safe technology use",["gossip","trouble-making","secrecy"],"Advocating spreads safe habits.")
H("684.d.6.A",3,"A scanner is a device that:","converts paper images into digital files",["prints pages","plays music","charges phones"],"Scanners digitize paper.")
H("684.d.6.A",4,"A device that captures video and sends it live over the internet is a:","webcam",["projector","printer","scanner"],"Webcams stream video.")
H("684.d.6.B",3,"The part of the computer where programs are run and instructions are processed is the:","CPU",["monitor","keyboard","speaker"],"The CPU processes.")
H("684.d.6.B",4,"The computer part that holds data and programs currently in use is:","RAM",["the mouse","the printer","the case"],"RAM provides working memory.")
H("684.d.6.C",3,"A server is a computer that:","provides data or services to other computers",["only plays games","has no network","cannot store files"],"Servers serve clients.")
H("684.d.6.C",4,"A web server delivers web pages to visitors when they:","request them with a browser",["unplug the cable","print a page","power off the router"],"Servers answer browser requests.")
H("684.d.6.D",3,"A disadvantage of running your own personal web server is that you must:","manage security and uptime yourself",["pay no attention","do nothing","never update"],"Self-hosting adds responsibility.")
H("684.d.6.D",4,"An advantage of using a hosting company over a personal server is:","professional maintenance and reliability",["higher risk","no support","more downtime"],"Hosts provide stability.")
H("684.d.6.E",3,"A keyboard and mouse are examples of:","input devices",["output devices","storage devices","power devices"],"They send data in.")
H("684.d.6.E",4,"A monitor and speakers are examples of:","output devices",["input devices","processors","network cards"],"They present results.")
H("684.d.6.F",3,"Making a document accessible means designing it so that:","people with disabilities can use it too",["only experts read it","it is hidden","it cannot print"],"Accessible documents work for everyone.")
H("684.d.6.F",4,"Using headings and alternative text in a document helps:","screen readers interpret it",["increase file size","remove text","hide colors"],"Structure aids assistive technology.")
H("684.d.6.G",3,"Bandwidth limits matter because visitors on slow connections may:","wait a long time for heavy pages",["see pages faster","never connect","pay less"],"Bandwidth affects load time.")
H("684.d.6.G",4,"Designing a site for a rural audience with limited connectivity suggests using:","lightweight pages and small images",["huge videos","giant images","heavy animations"],"Light pages suit slow links.")
H("684.d.6.H",3,"Organizing a website's files into folders such as images and styles creates a:","directory hierarchy",["file virus","broken link","backup error"],"Folders keep projects organized.")
H("684.d.6.H",4,"Keeping all the files for a web page in a clear structure helps to avoid:","broken links",["working pages","faster design","extra features"],"Good structure keeps paths correct.")
H("684.d.6.I",3,"A good web file name uses:","lowercase letters without spaces",["spaces and symbols","random capitals","emoji"],"Clean names avoid link errors.")
H("684.d.6.I",4,"Which file name is best for a web page?","about-us.html",["About Us!.html","about us.html","ABOUT US#1.html"],"Hyphens and lowercase are safe.")
H("684.d.6.J",3,"Using consistent colors and fonts across a website is an application of the principle of:","unity",["chaos","clutter","noise"],"Consistency creates unity.")
H("684.d.6.J",4,"Leaving enough empty space around content on a page makes it:","easier to read",["harder to read","messier","slower"],"White space improves readability.")

